// 참고용 변환 예시 — 원본은 Python 노트북 Part 0 · Part 5
import process from "node:process";

const SR = 16000; // 모든 음성 모델 입력 표준

interface Line {
  speaker: string;
  name?: string;
  start: number;
  end: number;
  text: string;
}
interface Summary {
  summary: string[];
  decisions: string[];
  action_items: { owner: string; task: string; due: string }[];
}
// 단계 함수는 pipeline · prompt 카드의 예시를 참고해 주입해요.
interface Stages {
  transcribeAlign(y: Float32Array): Promise<unknown>; // R1 받아쓰기 + 시각 정렬
  diarize(y: Float32Array, n: number | null): Promise<unknown>; // R2 화자 분리
  toLines(aligned: unknown, diar: unknown): { lines: Line[] }; // R3
  nameSpeakers(y: Float32Array, diar: unknown, enroll: Record<string, Float32Array> | null): Promise<Record<string, string>>;
  summarize(lines: Line[], transcript: string): Promise<{ summary: Summary; how: string }>; // R4
  renderMinutes(summary: Summary, lines: Line[], title: string): string;
}

// Colab 🔑 보안 비밀 대신 환경 변수에서 키 찾기 (키는 코드에 쓰지 않아요)
const secret = (name: string): string | undefined => process.env[name];
console.log("ANTHROPIC_API_KEY:", secret("ANTHROPIC_API_KEY") ? "✅ 있음 (Claude 요약)" : "❌ 없음 → 규칙 기반 요약");

const pad = (n: number): string => String(Math.floor(n)).padStart(2, "0");
const fmtTime = (t: number): string => `${pad(t / 60)}:${pad(t % 60)}`;

export async function makeMinutes(
  y: Float32Array,
  stages: Stages,
  { numSpeakers = null, enroll = null }: { numSpeakers?: number | null; enroll?: Record<string, Float32Array> | null } = {},
): Promise<{ markdown: string; summary: Summary }> {
  const aligned = await stages.transcribeAlign(y);
  const diar = await stages.diarize(y, numSpeakers);
  const { lines } = stages.toLines(aligned, diar);
  const names = await stages.nameSpeakers(y, diar, enroll);
  for (const ln of lines) ln.name = names[ln.speaker] ?? ln.speaker;
  const transcript = lines.map((l) => `[${fmtTime(l.start)}] ${l.name}: ${l.text}`).join("\n");
  const { summary, how } = await stages.summarize(lines, transcript);
  return { markdown: stages.renderMinutes(summary, lines, `회의록 (자동 생성 · 요약: ${how})`), summary };
}

