editdist.javascript:
// 참고용 변환 예시 — 원본은 Python 노트북 Part 1 (빈칸 1)
// 편집 거리 표: 칸 하나 = 정답 앞 i개를 결과 앞 j개로 바꾸는 최소 횟수
export function editDistance(r, h) {
  const n = r.length;
  const m = h.length;
  const d = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));
  for (let i = 0; i <= n; i++) d[i][0] = i; // 결과가 비었으면 정답을 모두 '빠짐'
  for (let j = 0; j <= m; j++) d[0][j] = j; // 정답이 비었으면 결과가 모두 '끼어듦'
  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= m; j++) {
      const cost = r[i - 1] === h[j - 1] ? 0 : 1; // 같음(0) 또는 바꿈(1)
      d[i][j] = Math.min(
        d[i - 1][j] + 1, // 빠짐 (D)
        d[i][j - 1] + 1, // 끼어듦 (I)
        d[i - 1][j - 1] + cost, // 같음 · 바꿈 (S)
      );
    }
  }
  return d;
}

const ref = "회의를 세 시에 시작합니다".split(" ");
const hyp = "회의를 3시에 바로 시작합니다".split(" ");
const d = editDistance(ref, hyp);
console.table(d); // 표로 보기
console.log("최소 고침 횟수 =", d.at(-1).at(-1)); // 2

