// 참고용 변환 예시 — 원본은 Python 노트북 Part 1 (빈칸 2)
// 편집 거리 (한 줄 배열로 줄인 버전)
function editDistance(r, h) {
  let prev = Array.from({ length: h.length + 1 }, (_, j) => j);
  for (let i = 1; i <= r.length; i++) {
    const cur = [i];
    for (let j = 1; j <= h.length; j++) {
      const cost = r[i - 1] === h[j - 1] ? 0 : 1;
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost);
    }
    prev = cur;
  }
  return prev[h.length];
}

// 고침 횟수를 '정답의 길이(N)'로 나눈다. 단어 단위면 WER, 글자 단위면 CER
const errorRate = (r, h) => editDistance(r, h) / r.length;
export const myWer = (ref, hyp) => errorRate(ref.split(" "), hyp.split(" "));
export const myCer = (ref, hyp) => errorRate([...ref], [...hyp]); // 공백도 한 글자

const pct = (x) => `${(x * 100).toFixed(1).padStart(6)}%`;
const pairs = [
  ["회의를 세 시에 시작합니다", "회의를 3시에 바로 시작합니다"],
  ["회의록 생성기를 만들어 봅시다", "회의록생성기를 만들어봅시다"],
  ["네 좋습니다", "네 네 네 좋습니다 감사합니다"],
];
for (const [r, h] of pairs) {
  console.log(`정답: ${r}\n결과: ${h}`);
  console.log(`  WER ${pct(myWer(r, h))} · CER ${pct(myCer(r, h))}\n`);
}

