// 참고용 변환 예시 — 원본은 Python 노트북 Part 2 (빈칸 4~6)
const DIG = "영일이삼사오육칠팔구";
const UNITS = ["", "십", "백", "천"];

// 숫자 → 한자어 읽기 (만 미만): 2026 → 이천이십육
export function num2kor(n) {
  if (n === 0) return "영";
  if (n >= 10000) return String(n); // 만 이상은 그대로 둠
  let s = "";
  [...String(n)].reverse().forEach((ch, i) => {
    const d = Number(ch); // i = 0(일의 자리), 1(십), 2(백), 3(천)
    if (d === 0) return;
    s = (d === 1 && i > 0 ? "" : DIG[d]) + UNITS[i] + s; // '일십' 대신 '십'
  });
  return s;
}

// 용어 사전: 바꿀 말(k) → 바꿀 표기(v)
const TERMS = { whisper: "위스퍼", api: "에이피아이", cer: "씨이알", pyannote: "파이아노트" };

export function normalize(text) {
  let s = text.toLowerCase(); // ① 소문자
  s = s.replace(/(?<=\d),(?=\d)/g, ""); // 2,500 → 2500
  s = s.replace(/[^\p{L}\p{N}\s_]/gu, " "); // ① 문장 부호 → 공백
  s = s.replace(/\d+/g, (m) => num2kor(Number(m))); // ② 숫자 → 한글
  for (const [k, v] of Object.entries(TERMS)) s = s.replaceAll(k, v); // ③ 용어 사전
  return s.replace(/\s+/g, " ").trim(); // ④ 공백 정리는 맨 마지막
}

console.log(normalize("Whisper로  10월 20일, API!")); // 위스퍼로 십월 이십일 에이피아이

