// 참고용 변환 예시 — 원본은 Python 노트북 Part 3
import { pipeline } from "@huggingface/transformers";

const SR = 16000;
const asr = await pipeline("automatic-speech-recognition", "onnx-community/whisper-small");

// R1: 받아쓰기 + 단어별 시각 (Python의 whisperx.align 대신 word timestamps)
export async function transcribeAlign(y) {
  const out = await asr(y, { language: "korean", return_timestamps: "word" });
  return out.chunks.map((c) => ({ word: c.text.trim(), start: c.timestamp[0], end: c.timestamp[1] ?? c.timestamp[0] }));
}

// R2: 말소리 구간을 에너지로 나누고, 구간 임베딩을 코사인 거리로 묶기 (단순화한 버전)
// embed(구간 Float32Array) → number[] 는 화자 임베딩 모델을 따로 연결해야 해요.
export function diarize(y, embed, threshold = 0.6) {
  const win = SR * 0.05; // 50ms 창
  const segs = [];
  for (let i = 0; i + win <= y.length; i += win) {
    const rms = Math.sqrt(y.subarray(i, i + win).reduce((a, v) => a + v * v, 0) / win);
    const t = i / SR;
    if (rms < 0.01) continue; // 묵음
    if (segs.length && t - segs.at(-1).end < 0.3) segs.at(-1).end = t + 0.05;
    else segs.push({ start: t, end: t + 0.05 });
  }
  const cos = (a, b) => a.reduce((s, v, i) => s + v * b[i], 0) / (Math.hypot(...a) * Math.hypot(...b));
  const centers = [];
  return segs
    .filter((s) => s.end - s.start > 0.3)
    .map((s) => {
      const e = embed(y.subarray(Math.floor(s.start * SR), Math.floor(s.end * SR)));
      let k = centers.findIndex((c) => 1 - cos(c, e) < threshold);
      if (k < 0) k = centers.push(e) - 1; // 새 화자
      return { ...s, speaker: `SPEAKER_${String(k).padStart(2, "0")}` };
    });
}

// R3: 단어를 화자 구간에 붙이고, 같은 화자면 이어 붙이기
export function toLines(words, diar) {
  const lines = [];
  for (const w of words) {
