// 참고용 변환 예시 — 원본은 Python 노트북 Part 3
import { pipeline } from "@huggingface/transformers";

const SR = 16000;
interface Word { word: string; start: number; end: number }
interface Seg { start: number; end: number; speaker: string }
interface Line { speaker: string; start: number; end: number; text: string }
type Embed = (seg: Float32Array) => number[]; // 화자 임베딩 모델을 따로 연결해야 해요

const asr = await pipeline("automatic-speech-recognition", "onnx-community/whisper-small");

// R1: 받아쓰기 + 단어별 시각 (Python의 whisperx.align 대신 word timestamps)
export async function transcribeAlign(y: Float32Array): Promise<Word[]> {
  const out = (await asr(y, { language: "korean", return_timestamps: "word" })) as {
    chunks: { text: string; timestamp: [number, number | null] }[];
  };
  return out.chunks.map((c) => ({ word: c.text.trim(), start: c.timestamp[0], end: c.timestamp[1] ?? c.timestamp[0] }));
}

// R2: 말소리 구간을 에너지로 나누고, 구간 임베딩을 코사인 거리로 묶기 (단순화한 버전)
export function diarize(y: Float32Array, embed: Embed, threshold = 0.6): Seg[] {
  const win = SR * 0.05; // 50ms 창
  const segs: { start: number; end: number }[] = [];
  for (let i = 0; i + win <= y.length; i += win) {
    const rms = Math.sqrt(y.subarray(i, i + win).reduce((a, v) => a + v * v, 0) / win);
    const t = i / SR;
    if (rms < 0.01) continue; // 묵음
    const last = segs.at(-1);
    if (last && t - last.end < 0.3) last.end = t + 0.05;
    else segs.push({ start: t, end: t + 0.05 });
  }
  const cos = (a: number[], b: number[]): number => a.reduce((s, v, i) => s + v * b[i], 0) / (Math.hypot(...a) * Math.hypot(...b));
  const centers: number[][] = [];
  return segs
    .filter((s) => s.end - s.start > 0.3)
    .map((s) => {
      const e = embed(y.subarray(Math.floor(s.start * SR), Math.floor(s.end * SR)));
      let k = centers.findIndex((c) => 1 - cos(c, e) < threshold);
      if (k < 0) k = centers.push(e) - 1; // 새 화자
      return { ...s, speaker: `SPEAKER_${String(k).padStart(2, "0")}` };
    });
}

// R3: 단어를 화자 구간에 붙이고, 같은 화자면 이어 붙이기
export function toLines(words: Word[], diar: Seg[]): Line[] {
  const lines: Line[] = [];
  for (const w of words) {
    const seg = diar.find((d) => w.start >= d.start && w.start <= d.end) ?? diar[0];
    const last = lines.at(-1);
    if (last && last.speaker === seg.speaker) Object.assign(last, { text: `${last.text} ${w.word}`, end: w.end });
    else lines.push({ speaker: seg.speaker, start: w.start, end: w.end, text: w.word });
  }
  return lines;
}

