// 참고용 변환 예시 — 원본은 Python 노트북 Part 5 (빈칸 9)
// normalize · cer 는 다른 카드(정규화 · WER vs CER)의 예시 모듈을 가져와요.
import { normalize } from "./normalize.mjs";
import { cer } from "./cer.mjs";

// 핵심 사항: 이 중 하나라도 나오면 '담음'
const KEY_POINTS = {
  "받아쓰기 모델 = 위스퍼 스몰": ["위스퍼", "whisper"],
  "화자 분리 = 파이아노트": ["파이아노트", "pyannote"],
  "평가 = 정규화 후 글자 오류율": ["오류율", "cer"],
  "박대리 · 수요일 · 단어 시각 정렬": ["수요일"],
  "이연구원 · 목요일 · 평가 스크립트": ["목요일"],
};

export function evaluate({ summary, refText, hypText }) {
  const summaryText = normalize(JSON.stringify(summary));
  const found = Object.fromEntries(
    Object.entries(KEY_POINTS).map(([k, kws]) => [k, kws.some((w) => summaryText.includes(normalize(w)))]),
  );
  const hit = Object.values(found).filter(Boolean).length;
  const score = hit / Object.keys(KEY_POINTS).length; // 핵심 사항 전체 = KEY_POINTS 의 개수

  const pct = (x) => `${(x * 100).toFixed(1)}%`;
  console.log("📋 평가표");
  console.log(`  받아쓰기 CER   정규화 전 ${pct(cer(refText, hypText))} → 정규화 후 ${pct(cer(normalize(refText), normalize(hypText)))}`);
  console.log(`  요약 점검 ${hit}/${Object.keys(KEY_POINTS).length}`);
  for (const [k, v] of Object.entries(found)) console.log(`    ${v ? "✅" : "⬜"} ${k}`);
  return score;
}

